from pathlib import Path
root=Path('/mnt/data/round3_work')

# 1) database schema + migrations
p=root/'database.py'
s=p.read_text()
s=s.replace("    quantity          INTEGER NOT NULL DEFAULT 0\n);", "    quantity          INTEGER NOT NULL DEFAULT 0,\n    cost_price        INTEGER NOT NULL DEFAULT 0,\n    min_margin_percent INTEGER NOT NULL DEFAULT 15\n);")
needle='    "ALTER TABLE products ADD COLUMN quantity INTEGER NOT NULL DEFAULT 0",\n'
if needle in s and 'ADD COLUMN cost_price' not in s:
    s=s.replace(needle, needle+'    "ALTER TABLE products ADD COLUMN cost_price INTEGER NOT NULL DEFAULT 0",\n    "ALTER TABLE products ADD COLUMN min_margin_percent INTEGER NOT NULL DEFAULT 15",\n')
# seed policies after schema seed, before existing admin seed
marker='    # Seed a default admin user, only if none exists yet\n'
seed="""    # Seed conservative high-risk approval policies.\n    default_policies = [\n        ('order.refund', 5000, 1, 1440, 1),\n        ('promotion.create', 20, 1, 1440, 1),\n        ('inventory.adjust', 10, 1, 1440, 1),\n    ]\n    for action, threshold_amount, two_person, expiry_minutes, enabled in default_policies:\n        conn.execute(\n            \"INSERT OR IGNORE INTO high_risk_action_policies\n             (action, threshold_amount, require_two_person, approval_expiry_minutes, enabled, updated_at)\n             VALUES (?, ?, ?, ?, ?, ?)\",\n            (action, threshold_amount, two_person, expiry_minutes, enabled, now()),\n        )\n\n"""
if marker in s and 'default_policies = [' not in s:
    s=s.replace(marker, seed+marker)
p.write_text(s)

# 2) new migration
mig=root/'migrations/versions/a19d4e8c71f2_business_control_layer.py'
mig.write_text('''"""Complete business control layer: product costs + governance escalation fields.\n\nRevision ID: a19d4e8c71f2\nRevises: 8b12c7d4e9f0\n"""\nfrom alembic import op\n\nrevision = "a19d4e8c71f2"\ndown_revision = "8b12c7d4e9f0"\nbranch_labels = None\ndepends_on = None\n\ndef upgrade():\n    op.execute("ALTER TABLE products ADD COLUMN cost_price INTEGER NOT NULL DEFAULT 0")\n    op.execute("ALTER TABLE products ADD COLUMN min_margin_percent INTEGER NOT NULL DEFAULT 15")\n    op.execute("ALTER TABLE business_exceptions ADD COLUMN assigned_to INTEGER")\n    op.execute("ALTER TABLE business_exceptions ADD COLUMN due_at TEXT")\n    op.execute("ALTER TABLE business_exceptions ADD COLUMN escalated_at TEXT")\n    op.execute("ALTER TABLE business_exceptions ADD COLUMN escalation_reason TEXT NOT NULL DEFAULT ''")\n\ndef downgrade():\n    # SQLite cannot reliably drop columns across supported versions; leave these\n    # additive columns in place during downgrade.\n    pass\n''')

# 3) governance_service additions
p=root/'governance_service.py'; s=p.read_text()
insert='''\n\ndef request_or_validate_approval(conn, *, action: str, requested_by: int, entity: str, entity_id: int,\n                                 amount: int = 0, reason: str = "", metadata: Optional[dict] = None,\n                                 approval_id: Optional[int] = None) -> Dict[str, Any]:\n    """Enforce a two-person approval policy when configured.\n\n    Returns allowed=True only when no approval is required or a still-valid\n    approval from another admin matches the requested action/entity/metadata.\n    Otherwise returns allowed=False with a newly-created pending approval.\n    """\n    if not policy_requires_approval(conn, action, amount):\n        return {"allowed": True, "approval_id": None, "required": False}\n    if approval_id:\n        row = conn.execute(\n            "SELECT * FROM admin_approval_requests WHERE id=? AND action=? AND entity=? AND entity_id=?",\n            (int(approval_id), action, entity, int(entity_id)),\n        ).fetchone()\n        if row and row["status"] == "approved" and int(row["requested_by"]) != int(requested_by):\n            meta_ok = True\n            try:\n                expected = json.loads(row["metadata_json"] or "{}")\n                for k, v in (metadata or {}).items():\n                    if expected.get(k) != v:\n                        meta_ok = False\n                        break\n            except Exception:\n                meta_ok = False\n            if meta_ok:\n                return {"allowed": True, "approval_id": int(approval_id), "required": True}\n    new_id = create_approval(conn, requested_by=requested_by, action=action, entity=entity,\n                              entity_id=entity_id, amount=amount, reason=reason, metadata=metadata)\n    return {"allowed": False, "approval_id": new_id, "required": True}\n\n\ndef open_exception(conn, *, code: str, severity: str, title: str, description: str,\n                   entity: str = "", entity_id: int = 0, assigned_to: int = 0,\n                   due_at: Optional[str] = None, metadata: Optional[dict] = None) -> int:\n    existing = conn.execute(\n        "SELECT id FROM business_exceptions WHERE code=? AND entity=? AND entity_id=? AND status='open' LIMIT 1",\n        (code, entity, int(entity_id or 0)),\n    ).fetchone()\n    if existing:\n        return int(existing[0])\n    row_id = add_exception(conn, code=code, severity=severity, title=title, description=description,\n                           entity=entity, entity_id=entity_id, metadata=metadata)\n    conn.execute(\n        "UPDATE business_exceptions SET assigned_to=?, due_at=? WHERE id=?",\n        (assigned_to or None, due_at, row_id),\n    )\n    conn.commit()\n    return row_id\n\n\ndef escalate_overdue_exceptions(conn, *, now_iso: Optional[str] = None) -> int:\n    now_iso = now_iso or _now()\n    rows = conn.execute(\n        "SELECT id, severity, title FROM business_exceptions WHERE status='open' AND due_at IS NOT NULL AND due_at < ? AND escalated_at IS NULL",\n        (now_iso,),\n    ).fetchall()\n    for row in rows:\n        conn.execute(\n            "UPDATE business_exceptions SET severity=CASE WHEN severity='critical' THEN 'critical' WHEN severity='high' THEN 'critical' ELSE 'high' END, escalated_at=?, escalation_reason='SLA deadline exceeded', updated_at=? WHERE id=?",\n            (now_iso, now_iso, int(row[0])),\n        )\n    conn.commit()\n    return len(rows)\n\n\ndef coupon_discount_with_margin(*, price: int, cost_price: int, discount_type: str, discount_value: int,\n                                min_margin_percent: int = 15) -> Dict[str, int]:\n    """Return a safe discount and resulting margin; never permits a known-cost\n    product to be sold below its configured minimum margin.\n    """\n    price = max(0, int(price or 0))\n    cost = max(0, int(cost_price or 0))\n    if discount_type == 'percent':\n        raw = int(round(price * int(discount_value or 0) / 100))\n    else:\n        raw = int(discount_value or 0)\n    raw = max(0, min(raw, max(price - 1, 0)))\n    floor_price = int(round(cost * (1 + max(0, int(min_margin_percent or 0)) / 100)))\n    safe_final = max(0 if not price else min(price, floor_price), price - raw) if cost else price - raw\n    safe_final = min(price, max(0, safe_final))\n    safe_discount = max(0, price - safe_final)\n    margin = safe_final - cost\n    return {"discount": safe_discount, "final_price": safe_final, "margin": margin, "floor_price": floor_price}\n'''
if 'def request_or_validate_approval' not in s:
    s += insert
p.write_text(s)

# 4) razorpay client: refund listing and order details
p=root/'razorpay_client.py'; s=p.read_text()
if 'def fetch_payment_refunds' not in s:
    s += '''\n\ndef fetch_payment_refunds(payment_id):\n    if not payment_id:\n        return []\n    resp = requests.get(f"{API_BASE}/payments/{payment_id}/refunds", auth=_auth(), timeout=15)\n    resp.raise_for_status()\n    return resp.json().get("items", [])\n'''
p.write_text(s)

# 5) reconciliation script replacement
p=root/'reconcile_razorpay.py'; p.write_text('''"""Reconcile local orders/refunds against Razorpay provider truth.\n\nSafe to run repeatedly. It detects missing payments, amount mismatches and\nprovider/local refund discrepancies. It never silently marks a mismatched\ntransaction successful.\n"""\nimport os, sys, logging\nfrom datetime import datetime, timezone, timedelta\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport database as db\nimport razorpay_client as rzp\nfrom governance_service import open_exception\n\nlogging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")\nlogger=logging.getLogger("reconcile_razorpay")\n\ndef main():\n    if not rzp.is_configured():\n        logger.warning("Razorpay not configured — skipping reconciliation.")\n        return\n    conn=db.get_db(); cutoff=(datetime.now(timezone.utc)-timedelta(minutes=30)).isoformat()\n    orders=conn.execute("SELECT * FROM orders WHERE created_at <= ? AND razorpay_order_id IS NOT NULL AND razorpay_order_id != '' ORDER BY created_at ASC", (cutoff,)).fetchall()\n    fixed=0; mismatches=0\n    for order in orders:\n        try:\n            payments=rzp.fetch_order_payments(order["razorpay_order_id"])\n        except Exception as exc:\n            open_exception(conn, code="provider_reconciliation_error", severity="high", title="Razorpay reconciliation failed", description=str(exc), entity="order", entity_id=int(order["id"]))\n            continue\n        captured=[p for p in payments if p.get("status")=="captured" and p.get("captured") is True]\n        total_captured=sum(int(p.get("amount") or 0) for p in captured)\n        expected_paise=int(order["amount"] or 0)*100\n        if captured and total_captured != expected_paise:\n            mismatches += 1\n            open_exception(conn, code="payment_amount_mismatch", severity="critical", title="Razorpay payment amount mismatch", description=f"Local ₹{order['amount']} vs provider paise {total_captured}", entity="order", entity_id=int(order["id"]), metadata={"expected_paise":expected_paise,"provider_paise":total_captured})\n            continue\n        if captured and not order["razorpay_payment_id"]:\n            p=captured[0]\n            conn.execute("UPDATE orders SET status='paid', payment_state='paid', order_state='paid', razorpay_payment_id=?, paid_at=? WHERE id=? AND status NOT IN ('cancelled','refunded')", (p.get("id"), db.now(), int(order["id"])))\n            fixed += 1\n        payment_id=order["razorpay_payment_id"] or (captured[0].get("id") if captured else None)\n        if payment_id:\n            try:\n                provider_refunds=rzp.fetch_payment_refunds(payment_id)\n                provider_ids={r.get("id") for r in provider_refunds if r.get("id")}\n                local=conn.execute("SELECT id, provider_refund_id, status FROM order_refunds WHERE order_id=?", (int(order["id"]),)).fetchall()\n                local_ids={r["provider_refund_id"] for r in local if r["provider_refund_id"]}\n                missing=provider_ids-local_ids\n                if missing:\n                    mismatches += len(missing)\n                    open_exception(conn, code="refund_reconciliation_mismatch", severity="high", title="Provider refund not recorded locally", description=f"Razorpay refunds missing locally: {sorted(missing)}", entity="order", entity_id=int(order["id"]), metadata={"provider_refund_ids":sorted(missing)})\n            except Exception as exc:\n                open_exception(conn, code="refund_reconciliation_error", severity="medium", title="Refund reconciliation failed", description=str(exc), entity="order", entity_id=int(order["id"]))\n    conn.commit(); conn.close()\n    logger.info("Reconciliation complete: repaired=%s mismatches=%s scanned=%s", fixed, mismatches, len(orders))\n\nif __name__ == "__main__": main()\n''')

print('patched core')
